import { tfLabelToTsLabel } from "../../engine/tf/index.js";
/**
 * Resolve a foreign app/element data lookup to its display name. Ref-only
 * lookups are intentionally namespace-only, so fall back through the
 * recursive pull's namespace -> refName and display-name -> refName maps.
 */
export function dataAspectDisplayName(ctx, kind, label) {
    const type = kind === "app" ? "elementum_app" : "elementum_element";
    const direct = ctx.dataName(type, label);
    if (direct !== undefined)
        return direct;
    const attrs = ctx.dataAttrs?.(type, label);
    if (typeof attrs?.name === "string")
        return attrs.name;
    const namespace = typeof attrs?.namespace === "string" ? attrs.namespace : undefined;
    if (namespace === undefined)
        return undefined;
    const refName = kind === "app"
        ? ctx.foreignAppRefNamespaces?.get(namespace)
        : ctx.foreignElementRefNamespaces?.get(namespace);
    if (refName === undefined)
        return undefined;
    const names = kind === "app" ? ctx.foreignAppRefNames : ctx.foreignElementRefNames;
    return [...(names?.entries() ?? [])].find(([, candidateRefName]) => candidateRefName === refName)?.[0];
}
/** Resolve the stable pulled catalog key for the same foreign lookup. */
export function dataAspectRefName(ctx, kind, label, displayName) {
    const type = kind === "app" ? "elementum_app" : "elementum_element";
    const attrs = ctx.dataAttrs?.(type, label);
    const namespace = typeof attrs?.namespace === "string" ? attrs.namespace : undefined;
    const byNamespace = kind === "app" ? ctx.foreignAppRefNamespaces : ctx.foreignElementRefNamespaces;
    if (namespace !== undefined) {
        const refName = byNamespace?.get(namespace);
        if (refName !== undefined)
            return refName;
    }
    const name = displayName ?? dataAspectDisplayName(ctx, kind, label);
    const byName = kind === "app" ? ctx.foreignAppRefNames : ctx.foreignElementRefNames;
    return name === undefined ? undefined : byName?.get(name);
}
/**
 * Resolve a foreign app/element data lookup to the full identity a caller
 * needs to build its own ref shape: the real display name/refName when the
 * target was pulled separately, degrading to a tfLabel-derived guess (with
 * the real namespace still attached) when it wasn't - never a bare guessed
 * name with no namespace, which matches nothing on the platform.
 */
export function resolveDataAspectTarget(ctx, kind, dataLabel) {
    const type = kind === "app" ? "elementum_app" : "elementum_element";
    const displayName = dataAspectDisplayName(ctx, kind, dataLabel);
    const refName = dataAspectRefName(ctx, kind, dataLabel, displayName);
    const attrs = ctx.dataAttrs?.(type, dataLabel);
    const namespace = typeof attrs?.namespace === "string" ? attrs.namespace : undefined;
    return {
        key: refName ?? tfLabelToTsLabel(dataLabel),
        name: displayName ?? refName ?? tfLabelToTsLabel(dataLabel),
        ...(namespace !== undefined ? { namespace } : {}),
        ...(refName !== undefined ? { catalogRef: true } : {}),
    };
}
